package fr.gemsofrod.encyclopedie.data

/** Traduktionen ins Deutsche des Namens und der beschreibenden Texte der Fossilien. */
object FossileTranslationsDe {
    val data: Map<String, FossileTranslation> = mapOf(
        "fossile-ammonite-madagascar" to FossileTranslation(
            nom = "Ammonit aus Madagaskar",
