        "fossile-ambre-baltique" to FossileTranslation(
            nom = "Baltischer Bernstein",
            descriptionCourte = "Das fossile Harz verschwundener Nadelwälder, der älteste organische Edelstein der menschlichen Schmuckgeschichte.",
            descriptionLongue = "Baltischer Bernstein entstand vor rund 44 Millionen Jahren aus dem Harz heute ausgestorbener Riesennadelbäume, deren Wälder einst Nordeuropa bedeckten. Von Flüssen mitgeführt und nach Stürmen an die Strände der Ostsee gespült, wird er seit der Bronzezeit von Menschen verarbeitet und gehandelt – die Bernsteinhandelsrouten zählen zu den ältesten dokumentierten Handelswegen Europas.",
            interetJoaillerie = "Hoch: traditioneller Schmuck Nordeuropas seit der Bronzezeit"
