        "fossile-ambre-inclusion" to FossileTranslation(
            nom = "Bernstein mit Insekteneinschluss",
            descriptionCourte = "Eine Mücke, eine Ameise oder eine Blüte, für die Ewigkeit in einem zu Stein gewordenen Harztropfen eingeschlossen.",
            descriptionLongue = "Der dominikanische Bernstein, jünger und in der Regel transparenter als der baltische, verdankt seinen Ruf dem außergewöhnlichen Reichtum seiner Einschlüsse: Insekten, Spinnen, kleine Blüten und gelegentlich sogar kleine Wirbeltiere finden sich darin mit einer Detailfülle gefangen, die dieses Fossil weit über die Kreise der Sammler hinaus bekannt gemacht hat – nicht zuletzt popularisiert durch die Fiktion rund um im Bernstein bewahrte DNA.",
            interetJoaillerie = "Hoch: jeder Einschluss ist einzigartig, hoher Mehrwert in der Sammlerschmuckherstellung"
